function setup() {
	createCanvas(windowWidth, windowHeight);
	// background(10, 10, 15);
	push()
	colorMode(HSB)
	distributiongType = {
		type:random(distributiongTypes),
		// type:'noise',
		seed:random()
	}
	const startHue = random(360)
	for(let i=0;i<3;i++){
		const hue = (startHue + i*120 + random(-20,20))%360
		let sat = 100
		let bri = 100
		if(i==1 && random()<0.5){
