function divide(x,y,w,h){
	if(w<50||height<50||(random()<0.2&&w<width/3&&h<height/3)){
		const centerX = x+w/2
		const centerY = y+h/2

		let initTimer;
		switch(distributiongType.type){
			case 'circle':
				if(distributiongType.seed<0.5){
					initTimer = map(dist(width/2,height/2,centerX,centerY),0,sqrt(width*width+height*height)/2,60,300)
				}else{
					initTimer = map(dist(width/2,height/2,centerX,centerY),0,sqrt(width*width+height*height)/2,300,60)
				}
				break
			case 'noise':
				initTimer = map(noise(centerX*0.005,centerY*0.005),0,1,0,480,true)
				break
			case 'linear':
				if(distributiongType.seed<0.25){
					initTimer = map(abs(centerX-width/2),0,width/2,60,300)
				}else if(distributiongType.seed<0.5){
					initTimer = map(abs(centerY-height/2),0,height/2,60,300)
				}else if(distributiongType.seed<0.5){
					initTimer = map(abs(centerX-width/2),0,width/2,300,60)
				}else{
					initTimer = map(abs(centerY-height/2),0,height/2,300,60)
				}
				break
		}

		ktRects.push(new KtRect({
			x:x,
			y:y,
			w:w,
			h:h,
			nowColor:0,
			timer:initTimer
		}))
		return;
	}

	const ratio = random(0.3,0.7)
	if(w>h){
		divide(x,y,w*ratio,h)
		divide(x+ratio*w,y,w*(1-ratio),h)
	}else{
		divide(x,y,w,h*ratio)
		divide(x,y+h*ratio,w,h*(1-ratio))
	}
}
class KtRect{
	constructor(argus){
		this.x = argus.x
		this.y = argus.y
		this.w = argus.w
		this.h = argus.h
		this.centerX = this.x+this.w/2
		this.centerY = this.y+this.h/2
		this.nowColor = 0
		this.timer = argus.timer||60
		this.duration = 90
		this.nowDirection = floor(random(0,4))
		this.transitionSeed = random()
		this.transitionType = floor(random(0,10))
	}
	initial(){
		this.timer = this.duration;
		this.nowColor++
		if(this.nowColor>colorPalette.length-1)this.nowColor=0
		this.nowDirection = floor(random(0,4))
		this.transitionSeed = random()
		this.transitionType = floor(random(0,10))
	}
	draw(){
		noStroke()
		const lastColor = this.nowColor>0?this.nowColor-1:colorPalette.length-1
		fill(colorPalette[lastColor])
		rect(this.x,this.y,this.w,this.h)

		//--maskRect--
		noFill()
		stroke(255,0)
		rect(this.x,this.y,this.w,this.h)
		push()
		drawingContext.clip()//mask
		push()
		translate(this.x,this.y)
		fill(colorPalette[this.nowColor])
		let x,y,w,h,t,r,d,maxD
		let xStart,yStart,xStart2,yStart2 //1
		let startAngle,rotateAngle,angle //3

		if(this.timer<=this.duration){
			switch(this.transitionType){
				case 0:
					t = easeInOutCubic(map(this.timer,this.duration,0,0,1));
					const target = (this.nowDirection<2)?this.h:this.w
					w = map(t,0,1,0,target)
					switch(this.nowDirection){
						case 0:
							rect(0,this.h-w,this.w,w)
							break
						case 1:
							rect(0,0,this.w,w)
							break
						case 2:
							rect(0,0,w,this.h)
							break
						case 3:
							rect(this.w-w,0,w,this.h)
							break
					}
					break
				case 1:
					t = easeInOutCubic(map(this.timer,this.duration,0,0,1));
					xStart = (this.transitionSeed*100)%1 * this.w
					yStart = (this.transitionSeed*10000)%1 * this.h
					push()
					rectMode(CENTER)
					x = map(t,0,1,xStart,this.w/2)
					y = map(t,0,1,yStart,this.h/2)
					w = map(t,0,1,0,this.w)
					h = map(t,0,1,0,this.h)
					r = map(t,0,1,this.w,0)
					rect(x,y,w,h,r)
					pop()
					break
				case 2:
					t = easeInOutExpo(map(this.timer,this.duration,0,0,1));
					switch(this.nowDirection){
						case 0:
							w = map(t,0,1,0,this.w)
							quad(0,0,w,0,this.w,this.h,this.w-w,this.h)
							break
						case 1:
							w = map(t,0,1,0,this.w)
							quad(this.w-w,0,0,this.h,w,this.h,this.w,0)
							break
						case 2:
							w = map(t,0,1,0,this.h)
							quad(0,0,0,w,this.w,this.h,this.w,this.h-w)
							break
						case 3:
							w = map(t,0,1,0,this.h)
							quad(0,this.h-w,this.w,0,this.w,w,0,this.h)
							break
					}
					break
				case 3:
					t = easeInOutExpo(map(this.timer,this.duration,0,0,1));
					startAngle = map(this.transitionSeed,0,1,0,TWO_PI)
					angle = map(t,0,1,0,PI)
					xStart = (this.transitionSeed*100)%1 * this.w
					yStart = (this.transitionSeed*10000)%1 * this.h
					x = map(t,0,1,xStart,this.w/2)
					y = map(t,0,1,yStart,this.h/2)
					d = sqrt(this.w*this.w+this.h*this.h)*2
					arc(x,y,d,d,startAngle-angle*1,startAngle+angle*1)
					break
				case 4:
					t = easeInOutExpo(map(this.timer,this.duration,0,0,1));
					startAngle = map(this.transitionSeed,0,1,-PI,PI)
					rotateAngle = map(t,0,1,startAngle,0)
					w = map(t,0,1,0,this.w)
					h = map(t,0,1,0,this.h)
					push()
					translate(this.w/2,this.h/2)
					rotate(rotateAngle)
					rectMode(CENTER)
					if(this.nowDirection<2){
						rect(0,0,this.w,h)
					}else{
						rect(0,0,w,this.h)
					}
					pop()
					break
				case 5:
					t = easeInOutExpo(map(this.timer,this.duration,0,0,1));
					let startX,startY
					let endX,endY
					switch(this.nowDirection){
						case 0:
							startX = 0
							startY = 0
							endX = this.w
							endY = this.h
							startAngle = atan2(this.h,this.w)
							break
						case 1:
							startX = this.w
							startY = this.h
							endX = 0
							endY = 0
							startAngle = atan2(-this.h,-this.w)
							break
						case 2:
							startX = this.w
							startY = 0
							endX = 0
							endY = this.h
							startAngle = atan2(this.h,-this.w)
							break
						case 3:
							startX = 0
							startY = this.h
							endX = this.w
							endY = 0
							startAngle = atan2(-this.h,this.w)
							break
					}
					x = map(t,0,1,startX,endX)
					y = map(t,0,1,startY,endY)
					angle = map(t,0,1,startAngle,startAngle+PI)
					d = sqrt(this.w*this.w+this.h*this.h)*2
					arc(x,y,d,d,startAngle,angle)
					arc(x,y,d,d,startAngle+PI,angle+PI)
					break
				case 6:
					t = easeInOutExpo(map(this.timer,this.duration,0,0,1));
					switch(this.nowDirection){
						case 0:
							x = 0
							y = 0
							break
						case 1:
							x = this.w
							y = this.h
							break
						case 2:
							x = this.w
							y = 0
							break
						case 3:
							x = 0
							y = this.h
							break
					}
					maxD = sqrt(this.w*this.w+this.h*this.h)*2
					d = map(t,0,1,0,maxD)
					circle(x,y,d)
					break
				case 7:
					t = easeInOutExpo(map(this.timer,this.duration,0,0,1));
					maxD = sqrt(this.w*this.w+this.h*this.h)
					d = map(t,0,1,0,maxD)
					circle(0,0,d)
					circle(this.w,0,d)
					circle(0,this.h,d)
					circle(this.w,this.h,d)
					break
				case 8:
					t = easeInOutCubic(map(this.timer,this.duration,0,0,1));
					if(this.w>this.h){
						const x = map(t,0,1,0,this.w)
						const maxD = this.w*2
						const d = map(t,0,1,0,maxD)
						if(this.nowDirection<2){
							circle(x,0,d)
							circle(this.w-x,this.h,d)
						}else{
							circle(this.w-x,0,d)
							circle(x,this.h,d)
						}
					}else{
						const y = map(t,0,1,0,this.h)
						const maxD = this.h*2
						const d = map(t,0,1,0,maxD)
						if(this.nowDirection<2){
							circle(0,y,d)
							circle(this.w,this.h-y,d)
						}else{
							circle(this.w,y,d)
							circle(0,this.h-y,d)
						}
					}
					break
				case 9:
					t = easeInOutExpo(map(this.timer,this.duration,0,0,1));
					xStart = (this.transitionSeed*10)%1 * this.w
					yStart = (this.transitionSeed*100000000)%1 * this.h
					xStart2 = (this.transitionSeed*10000)%1 * this.w
					yStart2 = (this.transitionSeed*1000000)%1 * this.h
					const p1 = createVector(map(t,0,1,xStart,0),
																	map(t,0,1,yStart,0))
					const p2 = createVector(map(t,0,1,xStart,this.w),
																	map(t,0,1,yStart,0))
					const p3 = createVector(map(t,0,1,xStart2,this.w),
																	map(t,0,1,yStart2,this.h))
					const p4 = createVector(map(t,0,1,xStart2,0),
																	map(t,0,1,yStart2,this.h))
					quad(p1.x,p1.y,p2.x,p2.y,p3.x,p3.y,p4.x,p4.y)
					break
			}
		}

		pop()
		pop()
		this.timer--
		if(this.timer<=0)this.initial()
	}
}
function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function easeInOutExpo(x) {
return x === 0
  ? 0
  : x === 1
  ? 1
  : x < 0.5 ? Math.pow(2, 20 * x - 10) / 2
  : (2 - Math.pow(2, -20 * x + 10)) / 2;
}


